test("claim tags scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-C", "20");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "perm-settle", "steward");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33", "from": "2026-03-16"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "terms": "20"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "terms": "20"}));
  expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ada, "Ben")).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ada, {"grade": "B", "gradeFrom": "2026-03-01"})).toBe(true);
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "0.40", "tags": "a"}));
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.35", "note": "n"}));
  await ui.refresh(pg_uma);
  expect(await ui.editPerson(pg_uma, p_cam, {"grade": "C", "gradeFrom": "2026-03-28"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.defer(pg_uma, c_ada_0, "2026-03-26")).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ben, "Ada")).toBe(true);
  const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "1.00", "date": "2026-03-01"}));
  await ui.refresh(pg_uma);
  expect(await ui.claimAction(pg_uma, c_cam_0, "void")).toBe(true);
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.25", "ref": "R-2", "tags": " c "}));
  await ui.refresh(pg_uma);

